import math

def is_not_prime(n: int) -> bool:
    if n < 2:
        return True
    limit = int(math.isqrt(n))
    for i in range(2, limit + 1):
        if n % i == 0:
            return True
    return False

import heapq

def heap_queue_largest(numbers, n):
    if n == 0 or not numbers:
        return []
    return heapq.nlargest(n, numbers)

def differ_At_One_Bit_Pos(a, b):
    xor = a ^ b
    return xor != 0 and (xor & (xor - 1)) == 0

def find_Rotations(s: str) -> int:
    n = len(s)
    if n <= 1:
        return 1
    for k in range(1, n):
        if s[k:] + s[:k] == s:
            return k
    return n

def remove_Occ(s, c):
    first = s.find(c)
    if first == -1:
        return s
    last = s.rfind(c)
    if first == last:
        return s[:first] + s[first+1:]
    return s[:first] + s[first+1:last] + s[last+1:]

import re

def text_lowercase_underscore(s: str) -> bool:
    # The pattern matches the entire string consisting of one or more groups of lowercase letters separated by single underscores
    # e.g. "a_b_c" matches, but "a__b" or "_abc" or "abc_" do not.
    pattern = r'^[a-z]+(_[a-z]+)+$'
    return bool(re.match(pattern, s))

def remove_dirty_chars(s1, s2):
    chars_to_remove = set(s2)
    return ''.join(c for c in s1 if c not in chars_to_remove)

def test_duplicate(arr):
    seen = set()
    for num in arr:
        if num in seen:
            return True
        seen.add(num)
    return False

def is_woodall(num):
    if num < 0:
        return False
    n = 1
    while True:
        woodall_candidate = n * (2 ** n) - 1
        if woodall_candidate == num:
            return True
        if woodall_candidate > num:
            return False
        n += 1

def check(n):
    rev = int(str(n)[::-1])
    return n == 2 * rev - 1

def opposite_Signs(x: int, y: int) -> bool:
    if x == 0 or y == 0:
        return False
    return (x * y) < 0

def is_octagonal(n):
    if n <= 0:
        return 0
    return n * (3 * n - 2)

def count_Substrings(s: str) -> int:
    n = len(s)
    prefix_sums = [0] * (n + 1)
    for i in range(n):
        prefix_sums[i + 1] = prefix_sums[i] + int(s[i])
    count = 0
    for start in range(n):
        for end in range(start, n):
            length = end - start + 1
            total = prefix_sums[end + 1] - prefix_sums[start]
            if total == length:
                count += 1
    return count

def smallest_num(lst):
    if not lst:
        return None
    return min(lst)

def max_difference(tuples):
    if not tuples:
        return 0
    return max(abs(a - b) for a, b in tuples)

def recursive_list_sum(lst):
    total = 0
    for item in lst:
        if isinstance(item, int):
            total += item
        elif isinstance(item, list):
            total += recursive_list_sum(item)
    return total

def pos_count(lst):
    count = 0
    for num in lst:
        if num > 0:
            count += 1
    return count

def bell_number(n):
    if n == 0:
        return 1
    bell = [1]
    for i in range(1, n + 1):
        row = [bell[-1]]
        for j in range(1, i + 1):
            row.append(row[-1] + bell[j - 1])
        bell = row
    return bell[0]

def is_Monotonic(array):
    if len(array) <= 1:
        return True
    non_decreasing = True
    non_increasing = True
    for i in range(1, len(array)):
        if array[i] < array[i - 1]:
            non_decreasing = False
        if array[i] > array[i - 1]:
            non_increasing = False
    return non_decreasing or non_increasing

def is_sublist(lst, sublst):
    if not sublst:
        return True
    if len(sublst) > len(lst):
        return False
    for i in range(len(lst) - len(sublst) + 1):
        if lst[i:i+len(sublst)] == sublst:
            return True
    return False

def get_equal(tuples):
    if not tuples:
        return True
    first_len = len(tuples[0])
    for t in tuples[1:]:
        if len(t) != first_len:
            return False
    return True

def comb_sort(arr):
    gap = len(arr)
    shrink = 1.3
    swapped = True

    while gap > 1 or swapped:
        gap = int(gap / shrink)
        if gap < 1:
            gap = 1

        swapped = False
        for i in range(len(arr) - gap):
            if arr[i] > arr[i + gap]:
                arr[i], arr[i + gap] = arr[i + gap], arr[i]
                swapped = True

    return arr

def dif_Square(n: int) -> bool:
    if n == 0:
        return True
    from math import isqrt
    abs_n = abs(n)
    for i in range(1, isqrt(abs_n) + 1):
        if n % i == 0:
            j = n // i
            # Check parity of absolute values of factors
            if (abs(i) % 2) == (abs(j) % 2):
                return True
            # Also check the pair with negative i
            ni = -i
            nj = n // ni if ni != 0 and n % ni == 0 else None
            if nj is not None and (abs(ni) % 2) == (abs(nj) % 2):
                return True
    return False

def is_samepatterns(patterns, sequence):
    if len(patterns) != len(sequence):
        return False

    def encode(lst):
        mapping = {}
        pattern = []
        next_id = 0
        for item in lst:
            if item not in mapping:
                mapping[item] = next_id
                next_id += 1
            pattern.append(mapping[item])
        return pattern

    return encode(patterns) == encode(sequence)

import math

def volume_sphere(radius):
    return (4/3) * math.pi * radius**3

def sequence(n):
    if n == 1 or n == 2:
        return 1
    a = [0] * (n + 1)
    a[1], a[2] = 1, 1
    for i in range(3, n + 1):
        a[i] = a[a[i - 1]] + a[i - a[i - 1]]
    return a[n]

import math

def surfacearea_sphere(radius):
    return 4 * math.pi * radius ** 2

