def is_undulating(n: int) -> bool:
    s = str(n)
    if len(s) < 2:
        return False
    first, second = s[0], s[1]
    if first == second:
        return False
    for i, ch in enumerate(s):
        if i % 2 == 0 and ch != first:
            return False
        if i % 2 == 1 and ch != second:
            return False
    return True

def index_minimum(lst):
    if not lst:
        return None
    return min(lst, key=lambda x: x[1])[0]

def Find_Min_Length(lst):
