        return 0
    return min(len(sublist) for sublist in lst)

def divisor(n: int) -> int:
    if n == 0:
        return 0
    n = abs(n)
    count = 0
    for i in range(1, n + 1):
        if n % i == 0:
            count += 1
    return count

