def frequency_lists(lst):
    freq = {}
    for sublist in lst:
        for item in sublist:
            freq[item] = freq.get(item, 0) + 1
    return freq

import math

def multiply_num(nums):
    if not nums:
        return 0
    product = 1
    for num in nums:
        product *= num
    return product / len(nums)

def decimal_to_binary(n: int) -> str:
    if n == 0:
        return '0'
    return bin(n)[2:]

def next_smallest_palindrome(n: int) -> int:
    s = str(n)
    length = len(s)

    # If all 9's, next palindrome is 10...01
    if all(ch == '9' for ch in s):
        return int('1' + ('0' * (length - 1)) + '1')

    def make_palindrome(left, middle, odd_length):
        if odd_length:
            return left + middle + left[::-1]
        else:
            return left + left[::-1]

    odd_length = (length % 2 != 0)
    if odd_length:
        left = s[:length // 2]
        middle = s[length // 2]
        right = s[length // 2 + 1:]
    else:
        left = s[:length // 2]
        middle = ''
        right = s[length // 2:]

    # Construct palindrome by mirroring left + middle
    palindrome = make_palindrome(left, middle, odd_length)
    if int(palindrome) > n:
        return int(palindrome)

    # Need to increment the middle part
    if odd_length:
        # Increment the middle digit and handle carry
        middle_num = int(middle)
        left_num = int(left) if left else 0

        # Combine left + middle as a number to increment
        combined = int(left + middle)
        combined += 1
        combined_str = str(combined)

        # If length increased after increment (e.g. 99 + 1 = 100)
        if len(combined_str) > len(left + middle):
            # This means carry overflow, so palindrome length increases
            # For example: 999 -> 1001 handled above, so here just mirror accordingly
            left = combined_str[:-1]
            middle = combined_str[-1]
        else:
            left = combined_str[:-1]
            middle = combined_str[-1]

        palindrome = make_palindrome(left, middle, True)
        return int(palindrome)
    else:
        # Even length: increment left half and mirror
        left_num = int(left)
        left_num += 1
        left_str = str(left_num)

        # If length increased after increment (e.g. 99 -> 100)
        if len(left_str) > len(left):
            # For example: 9999 -> 10001 handled above, so here just mirror accordingly
            palindrome = left_str + left_str[:-1][::-1]
        else:
            palindrome = left_str + left_str[::-1]
        return int(palindrome)

