def kth_element(arr, k):
    if k < 1 or k > len(arr):
        raise IndexError("k is out of bounds")
    return arr[k-1]

def eulerian_num(n, m):
    if m < 0 or m >= n:
        return 0
    if n == 0 and m == 0:
        return 1
    # Use memoization to avoid recomputation
    memo = {}

    def helper(n, m):
        if m < 0 or m >= n:
            return 0
        if n == 0 and m == 0:
            return 1
        if (n, m) in memo:
            return memo[(n, m)]
        val = (n - m) * helper(n - 1, m - 1) + (m + 1) * helper(n - 1, m)
        memo[(n, m)] = val
        return val

    return helper(n, m)

def common_in_nested_lists(nested_lists):
    if not nested_lists:
        return []
    common_elements = set(nested_lists[0])
    for lst in nested_lists[1:]:
        common_elements &= set(lst)
        if not common_elements:
            return []
    return list(common_elements)

import re

def check_integer(s: str) -> bool:
    return bool(re.fullmatch(r'[+-]?\d+', s))

def tuple_to_int(t):
    if not t:
        return 0
    return int(''.join(str(i) for i in t))

def search(arr):
    n = len(arr)
    for i in range(0, n - 1, 2):
        if arr[i] != arr[i + 1]:
            return arr[i]
    return arr[-1]

def max_product_tuple(lst):
    if not lst:
        return 0
    max_product = abs(lst[0][0] * lst[0][1])
    for a, b in lst:
        product = abs(a * b)
        if product > max_product:
            max_product = product
    return max_product

def amicable_numbers_sum(n):
    if n < 1:
        return 0

    def sum_proper_divisors(x):
        if x == 1:
            return 0
        total = 1
        limit = int(x**0.5)
        for i in range(2, limit + 1):
            if x % i == 0:
                total += i
                other = x // i
                if other != i:
                    total += other
        return total

    amicable_set = set()
    for num in range(2, n + 1):
        if num not in amicable_set:
            s = sum_proper_divisors(num)
            if s != num and s > 0:
                if sum_proper_divisors(s) == num:
                    # Add both numbers if either is within the limit
                    if s <= n:
                        amicable_set.add(num)
                        amicable_set.add(s)
                    else:
                        # If s > n but num <= n, add num only
                        amicable_set.add(num)

    return sum(amicable_set)

import cmath

def angle_complex(z):
    return cmath.phase(z)

def find_length(s):
    if not s:
        return 0
    arr = [1 if ch == '0' else -1 for ch in s]
    max_ending_here = max_so_far = 0
    for x in arr:
        max_ending_here = max(0, max_ending_here + x)
        max_so_far = max(max_so_far, max_ending_here)
    return max_so_far

def sum(a, b):
    import math

    a, b = abs(a), abs(b)
    if a == 0 and b == 0:
        return 0
    gcd = a if b == 0 else b if a == 0 else math.gcd(a, b)

    total = 0
    limit = int(math.isqrt(gcd))
    for i in range(1, limit + 1):
        if gcd % i == 0:
            total += i
            if i != gcd // i:
                total += gcd // i
    return total

def long_words(n, text):
    words = text.split()
    if n <= 0:
        return [word for word in words if len(word) > 0]
    return [word for word in words if len(word) > n]

def magic_square_test(matrix):
    if not matrix or not matrix[0]:
        return False
    n = len(matrix)
    for row in matrix:
        if len(row) != n:
            return False
    target_sum = sum(matrix[0])
    for row in matrix:
        if sum(row) != target_sum:
            return False
    for col in range(n):
        if sum(matrix[row][col] for row in range(n)) != target_sum:
            return False
    if sum(matrix[i][i] for i in range(n)) != target_sum:
        return False
    if sum(matrix[i][n - 1 - i] for i in range(n)) != target_sum:
        return False
    return True
